ofile IS NULL;
UPDATE companies SET description='SPF Electric, LLC operates from Angleton, Texas, where it has served the electrical power sector for over 25 years.

The shop specializes in electrical system fabrication, including bus bar fabrication (precision cutting, bending, punching, and shearing of copper and aluminum, plus aluminum bus bar welding), switchgear fabrication, G10/GP03 glass-epoxy components such as barriers and bus supports, relay panels, switchgear doors, and powder coating. All work is performed in-house using CNC cutting, vertical and horizontal press brakes, an iron worker, welding and stud welding equipment.

SPF Electric serves industrial, petrochemical, and electrical testing markets, as well as manufacturers, installers, and contractors who need custom electrical components. Typical projects involve switchgear, motor control centers, and transformers for facilities along the Texas Gulf Coast.

The company emphasizes that keeping every service under one roof enables faster turnarounds—quotes within three to five days, rush jobs in one to two weeks, and normal orders in four to six weeks—while maintaining quality through its CAD library of factory drawings for relays, switches, latches, and other accessories.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Bus fabrication", "Switchgear fabrication", "G10/GP03 fabrication", "Relay panels & switchgear doors", "Powder coating", "Precision cutting", "Bending", "Punching", "Shearing", "Aluminum bus bar welding", "CNC cutting", "Vertical press brakes", "Horizontal press brakes", "Iron worker", "Welding", "Stud welding", "Reverse engineering", "CAD design", "Drafting", "Gasket installation", "Hardware assembly"], "industries": ["Industrial", "Petrochemical", "Electrical testing", "Manufacturers", "Installers", "Contractors"], "materials": ["Copper", "Aluminum", "G10/GP03 (glass epoxy)"], "equipment": ["CNC cutting", "Vertical press brakes", "Horizontal press brakes", "Iron worker", "Welding equipment", "Stud welding equipment"], "volume": "", "lead_time": "Rush: 1-2 weeks; Normal: 4-6 weeks; Quote turnaround: 3-5 days", "tolerances": "", "built_on": [], "facts_used": ["Location: Angleton, Texas -> /", "Services: Bus fabrication, Switchgear fabrication, G10/GP03, Relay Panels & Switchgear Doors, Powder Coating -> /", "Capabilities: precision cutting, bending, punching, shearing of copper and aluminum bus bar, aluminum bus bar welding -> /services", "Equipment: CNC cutting, vertical and horizontal press brakes, iron worker, welding, stud welding -> /services", "Industries: industrial, petrochemical, electrical testing markets -> /about-us (blog post)", "Customer types: Manufacturers, Installers & Contractors -> /", "Experience: nearly 20 years experience -> /", "Experience: over 25 years immersion in electrical power sector -> /about", "In-house services: all services in-house for quicker turnarounds -> /", "Quote turnaround: accurate quote within 3-5 days -> /", "Lead times: Rush 1-2 weeks, Normal 4-6 weeks -> /", "Reverse engineering: hundreds of doors, panels, covers for switchgear, MCCs, transformers -> /about", "CAD department: state-of-the-art CAD department with factory drawings repository -> /about", "Materials: copper, aluminum, G10/GP03 -> /services"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We specialize in precision cutting, bending, punching, and shearing of copper and aluminum bus bar, along with expert Aluminum bus bar welding.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='spf-electric' AND approved AND profile IS NULL;
UPDATE companies SET description='SPI Semicon, headquartered in Ogden, Utah, traces its roots to 1970. The company was formed through the merger of two industry leaders, Semicon Systems and Semiconductor Products, combining decades of expertise in semiconductor packaging.

The company specializes in advanced semiconductor packaging, spanning front-end wafer fabrication to back-end finished devices. Its manufacturing processes include injection molding, vacuum forming, die-cutting, extrusion, and custom-made parts. Operations are supported by state-of-the-art facilities in the United States and the Philippines.

SPI Semicon serves the semiconductor industry, providing packaging solutions and components that meet or exceed EIA-541 and ESD 5.11.1 standards for resistivity and static protection. Its customer base includes semiconductor manufacturers requiring high-reliability packaging for advanced wafers and devices.

The company emphasizes innovation, quality, and exceptional service as its differentiators, backed by an ISO 9001 certified quality management system. Its unique product designs and unmatched packaging options are engineered to exceed the highest industry standards, reflecting a commitment to precision and reliability that powers technology worldwide.', certifications=ARRAY['ISO 9001']::text[], profile='{"capabilities": ["Semiconductor packaging", "Front-end wafer fabrication", "Back-end device finishing", "Injection molding", "Vacuum forming", "Die-cutting", "Extrusion", "Custom part manufacturing", "ESD protective packaging", "EIA-541 compliance", "ESD 5.11.1 compliance"], "industries": ["Semiconductor"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["ISO 9001 certified quality management system", "Manufacturing facilities in the United States and the Philippines", "Advanced injection molding, vacuum forming, die-cutting, and extrusion capabilities", "Components meeting EIA-541 and ESD 5.11.1 standards", "Formed from the merger of Semicon Systems and Semiconductor Products"], "facts_used": ["Founded in 1970 -> /about-us", "Headquartered in Ogden, Utah -> db", "Formed through merger of Semicon Systems and Semiconductor Products -> /about-us", "Facilities in United States and Philippines -> /about-us", "ISO 9001 certified -> /about-us, /quality", "Processes: injection molding, vacuum forming, die-cutting, extrusion, custom parts -> /about-us, /", "Products: semiconductor packaging, components meeting EIA-541 and ESD 5.11.1 -> /about-us, db", "Serves semiconductor industry -> /about-us, /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "At SPI/Semicon, we manufacture semiconductor packaging solutions as advanced as the wafers they protect.", "founded_year": "1970", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownersh