UPDATE companies SET description='Sandridge Crafted Foods traces its roots to 1960 when Vincent R. Sandridge began selling vacuum-packed deli meats in Cuyahoga Falls, Ohio. The company, now headquartered in Morton, Illinois, remains a third-generation, family-owned operation. Vincent’s son Mark D. Sandridge joined in 1976, later purchasing the business in 1997 and expanding into kettle-cooked soups, sauces, and sous vide proteins. Today, Mark’s sons Jordan and Dane serve as co-presidents, steering the business alongside nearly 1,000 employees across multiple facilities.

The company produces chef-crafted fresh foods including deli salads, soups, sauces, sous vide proteins, and assembled meal kits. Core technologies include high-pressure processing (HPP) for preservative-free shelf-life extension, European-inspired kettle cooking for layered flavors, and precision sous vide cooking. A 2023-opened Center of Excellence in Medina, Ohio, houses a culinary R&D team that runs a “bench-to-box” development process.

Sandridge serves college and university dining, deli and prepared-food retailers, foodservice distributors, and healthcare operators. Its branded lines—Grandma’s®, Melch’s®, and the new Simply Crafted™—appear in retail and foodservice channels, while private-label and co-pack programs supply custom formulations for national and regional brands.

The founding vision centered on fresh, authentic food that fosters community. Leadership emphasizes culinary innovation backed by food-science rigor, a GFSI/SQFI-certified safety program, and a vertically integrated cold chain to deliver “remarkably fresh” products without artificial preservatives.', certifications=ARRAY['HACCP','GFSI (SQFI)']::text[], profile='{"capabilities": ["High Pressure Processing (HPP)", "European-inspired kettle cooking", "Sous vide cooking", "Blanching", "Vegetable cleaning and trimming", "Meal kit assembly and ingredient kitting", "Private label and co-pack manufacturing", "Custom recipe development and formulation", "Culinary R&D and \"bench-to-box\" product commercialization", "Food safety management (HACCP, GFSI/SQFI)", "Cold chain management and refrigerated distribution", "Shrink reduction and inventory optimization support", "Marketing and brand storytelling resources"], "industries": ["College and university dining", "Deli and prepared foods", "Foodservice distribution", "Healthcare foodservice", "Retail grocery"], "materials": [], "equipment": ["High Pressure Processing (HPP) lines (two)", "European-inspired kettle cooking equipment", "Sous vide cooking systems", "Blanching system", "Vegetable cleaning and trimming line"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["High Pressure Processing (HPP) for extended shelf life without preservatives", "European-inspired kettle cooking for layered, slow-cooked flavors", "Sous vide cooking for precise texture and flavor retention", "\"Bench-to-box\" culinary development process with dedicated chef and food-science team", "Integrated cold-chain logistics via MDS Inc. refrigerated distribution network"], "facts_used": ["Founded 1960 by Vincent R. Sandridge -> /about-us", "Third-generation family-owned -> /about-us", "Headquarters in Morton, Illinois -> db", "Nearly 1,000 employees -> /about-us", "Facilities in Medina, OH; Morton, IL; New Oxford, PA -> /about-us", "Center of Excellence in Medina, OH -> /", "Core technologies: HPP, kettle cooking, sous vide -> /capabilities", "Products: deli salads, soups, sauces, sous vide proteins, meal kits -> /about-us, /capabilities", "Brands: Grandma''s\u00ae, Melch''s\u00ae, Simply Crafted\u2122 -> /about-us", "Industries served: College & University, Deli/Prepared Foods, Foodservice, Healthcare -> /", "Certifications: HACCP, GFSI/SQFI -> /capabilities", "Equipment: HPP lines, kettle equipment, sous vide systems, blanching system, veggie prep line -> /capabilities", "Private label/co-pack and meal assembly -> /capabilities", "Cold chain logistics via MDS Inc. -> /capabilities", "Culinary R&D team with chefs Mark Piciulo, Ray Toroyan, Matthew Ostrowski, Sam Brogan, Dr. Soma Gandikota -> /", "Rebranded to Sandridge Crafted Foods in 2023 -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Sandridge isn''t just a food manufacturer, we''re obsessed with fresh, flavorful food.", "founded_year": "1960", "employee_count": "nearly 1,000", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/sandridge-food-corporation/"], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='sandridge-crafted-foods' AND approved AND profile IS NULL;
UPDATE companies SET description='Sands Electric Co. has operated from Wheeling, West Virginia since its founding in 1896. The company remains family owned and operated, serving as an electrical wholesale distributor for the Upper Ohio Valley region.

As a wholesale distributor, Sands Electric stocks thousands of electrical products from industry brands. The company operates from a location at 52 18th Street in Wheeling, maintaining business hours Monday through Friday, 8:00 a.m. to 5:00 p.m.

The distributor supplies customers across the Upper Ohio Valley, providing electrical materials to contractors, industrial facilities, and commercial projects in the region.

